// Molaplan web app service worker (generated by tool/web/build_web.sh – do not edit build/web/sw.js).
// App shell offline + installable PWA. Only the app's own files are handled: /tilaa (the shop)
// and every other path are left to the network. API calls (Supabase, relay, ntfy) are never cached.
'use strict';
const VERSION = '__VERSION__';
const CACHE = 'molaplan-app-' + VERSION;
const FONTS = 'molaplan-fonts-v1';
const PRECACHE = __PRECACHE__;
const APP_PREFIXES = ['/assets/', '/canvaskit/', '/icons/'];
const APP_FILES = new Set(['/', '/index.html', '/main.dart.js', '/flutter.js', '/flutter_bootstrap.js',
  '/manifest.json', '/favicon.png', '/version.json']);

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((c) => c.addAll(PRECACHE.map((u) => new Request(u, { cache: 'reload' })))).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const k of await caches.keys()) {
      if (k.startsWith('molaplan-app-') && k !== CACHE) await caches.delete(k);
    }
    await self.clients.claim();
  })());
});

function isApp(url) {
  return url.origin === self.location.origin &&
    (APP_FILES.has(url.pathname) || APP_PREFIXES.some((p) => url.pathname.startsWith(p)));
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  // Google Fonts used by the Flutter engine: cache-first (fonts never change for a URL).
  if (url.origin === 'https://fonts.gstatic.com') {
    event.respondWith(caches.open(FONTS).then(async (c) => (await c.match(req)) || fetch(req).then((r) => { if (r.ok) c.put(req, r.clone()); return r; })));
    return;
  }
  if (url.origin !== self.location.origin) return;
  if (req.mode === 'navigate') {
    if (url.pathname !== '/' && url.pathname !== '/index.html') return; // e.g. /tilaa
    // Network first so a new release shows at once; the cached shell when offline.
    event.respondWith(fetch(req).then((r) => {
      if (r.ok) caches.open(CACHE).then((c) => c.put('/', r.clone()));
      return r;
    }).catch(async () => (await caches.match('/', { cacheName: CACHE })) || Response.error()));
    return;
  }
  if (!isApp(url)) return;
  event.respondWith(caches.open(CACHE).then(async (c) => {
    const hit = await c.match(req, { ignoreSearch: url.pathname === '/version.json' });
    if (hit) return hit;
    const r = await fetch(req);
    if (r.ok) c.put(req, r.clone());
    return r;
  }));
});
